const BOOKS={cet6:{label:'CET-6',title:'六级词库',mark:'6',dataset:'ecdict-cet6-v1',description:'ECDICT 六级标签词条，按通用语料参考顺序学习。',words:window.WORDLEAF_WORDS,meanings:window.WORDLEAF_MEANINGS,examples:window.WORDLEAF_EXAMPLES||{}},...window.WORDLEAF_EXTRA_BOOKS};
