function validateLibrary(data){const previous=activeMode,previousWords=WORDS,previousMeanings=MEANINGS;try{if(data&&[1,2].includes(data.version)){const mode=Object.keys(BOOKS).find(id=>BOOKS[id].dataset===data.dataset);if(!mode)throw Error('未知词库');useBook(mode,data);return{version:3,activeMode:mode,books:{[mode]:validate(data)}};}if(!data||data.version!==3||!own(BOOKS,data.activeMode)||!data.books||typeof data.books!=='object'||Array.isArray(data.books)||!own(data.books,data.activeMode))throw Error('无效备份');const books={};for(const[id,book]of Object.entries(data.books)){if(!own(BOOKS,id))throw Error('未知词库');useBook(id,book);books[id]=validate(book);}return{version:3,activeMode:data.activeMode,books};}finally{useBook(previous);WORDS=previousWords;MEANINGS=previousMeanings;WORD_MAP=new Map(WORDS.map(w=>[w.w,w]));}}
let library={version:3,activeMode,books:{}},state=fresh(),page='home',query='',filter='all',tierFilter='all',limit=50,study=null,modal=null,undoAction=null,toastTimer,tick=0,readFailed=false,calendarOffset=0;
try{const raw=window.Android?Android.getState():localStorage.getItem('wordleaf-state');if(raw){library=validateLibrary(JSON.parse(raw));useBook(library.activeMode,library.books[library.activeMode]);state=library.books[activeMode];}}catch(e){readFailed=true;setTimeout(()=>toast('进度暂时无法读取，请先恢复有效备份；当前不会覆盖原数据。'),500);}
const progress=w=>own(state.words,w)?state.words[w]:emptyProgress(),today=()=>state.history[dayKey()]||emptyHistory(),weak=p=>p.meaningWeak||p.spellWeak;
const availableWords=()=>activeMode==='cet6'?(state.activeList==='custom'&&state.collection?state.collection.ids.map(w=>WORD_MAP.get(w)):BOOKS.cet6.words):WORDS;
const collectionLabel=()=>activeMode==='cet6'?(state.activeList==='custom'?state.collection.name:'六级完整词库'):BOOKS[activeMode].title;
const pool=()=>state.plan.ids.map(w=>WORD_MAP.get(w));
