function planStats(){const p=pool();return{total:p.length,learned:p.filter(w=>progress(w.w).reps>0&&!progress(w.w).known).length,known:p.filter(w=>progress(w.w).known).length,mastered:p.filter(w=>progress(w.w).stage>=4&&!progress(w.w).known).length};}
const completedDay=h=>!!(h&&h.newTarget>0&&h.new.length>=h.newTarget);
