function learningDays(){const dates=new Set();for(const book of Object.values(allProfiles()))for(const[key,h]of Object.entries(book.history))if(key<=dayKey()&&completedDay(h))dates.add(key);return dates;}
function streak(dates=learningDays()){let n=0,d=new Date();if(!dates.has(dayKey(d)))d.setDate(d.getDate()-1);while(dates.has(dayKey(d))){n++;d.setDate(d.getDate()-1);}return n;}
function longestStreak(dates){let longest=0,run=0,previous='';for(const key of [...dates].sort()){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()-1);run=dayKey(d)===previous?run+1:1;longest=Math.max(longest,run);previous=key;}return longest;}
function lockDailyTarget(queue){const unlearned=queue.filter(word=>!progress(word).reps&&!progress(word).known);if(!unlearned.length||today().newTarget)return;const key=dayKey();if(!own(state.history,key))state.history[key]=emptyHistory();const available=new Set([...newWords().map(w=>w.w),...unlearned]);state.history[key].newTarget=Math.min(state.goal,today().new.length+available.size);}
