  for(let i=1;i<=days;i++){const key=prefix+'-'+String(i).padStart(2,'0'),complete=dates.has(key),practiced=profiles.some(book=>book.history[key]&&book.history[key].words.length),isToday=key===dayKey(),future=key>dayKey(),status=complete?'学习达标':practiced?'有练习，未记录达标':'未打卡';cells.push(`<span class="calendar-day ${complete?'complete':practiced?'practiced':''} ${isToday?'today':''} ${future?'future':''}" aria-label="${key}，${status}" ${isToday?'aria-current="date"':''}>${i}${complete?icon('check'):'<i aria-hidden="true"></i>'}</span>`);}
