function shell(content,nav=true){document.body.style.overflow=modal?'hidden':'';document.getElementById('app').innerHTML=`<div class="shell">${content}${nav?`<nav class="bottom-nav" aria-label="主导航">${[['home','home','今日'],['book','book','词库'],['stats','chart','我的']].map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav>`:''}</div><div id="modal-root"></div>`;if(modal)renderModal();}
