function goalOptions(value){const list=[5,10,20,30,50,100];if(!list.includes(value))list.push(value);return list.sort((a,b)=>a-b).map(v=>`<option value="${v}" ${v===value?'selected':''}>${v} 词</option>`).join('');}
function renderHome(){
  const done=selectedNewToday(),left=remaining(),due=plannedReviewWords().length,backlog=Math.max(0,dueWords().length-due),ps=planStats(),weakList=weakWords(),saved=unfinished(state.session);
  shell(`<header class="brand"><div class="brand-name"><img src="leaf.svg" alt=""><span>词芽<small>WORDLEAF</small></span></div><button class="tag mode-trigger" data-action="mode" aria-label="切换学习模式，当前 ${BOOKS[activeMode].label}" aria-haspopup="dialog">${BOOKS[activeMode].label}</button></header><main class="home"><div class="today-heading"><div><p class="eyebrow">${new Date().getMonth()+1} 月 ${new Date().getDate()} 日</p><h1>今日学习</h1></div><span class="day-streak">连续达标 ${streak()} 天</span></div>
  <button class="route-summary" data-action="plan"><div><strong>${esc(collectionLabel())} · ${ROUTES[state.plan.route]}</strong><span>${ps.total} 词 · 每天 ${state.plan.minutes} 分钟</span></div><span class="route-change">${state.planChosen?'调整计划':'选择计划'}</span></button>
  <section class="today-panel" aria-label="今日任务"><div class="task-counts"><div><span>待学新词</span><strong>${left}<small>词</small></strong><p>今日已学 ${done} / ${dailyGoal()}</p></div><div><span>今日待复习</span><strong>${due}<small>词</small></strong><p>已复习 ${today().reviewed.length} · 额度 ${state.reviewGoal}</p></div></div><button class="primary" data-action="${saved?'resume':'start'}" data-id="daily" ${!saved&&!left&&!due?'disabled':''}>${saved?'继续上次学习':left||due?'开始今日学习':'今日计划已完成'} ${icon('arrow')}</button><p class="session-note">${saved?`已保留第 ${state.session.index+1} / ${state.session.queue.length} 个词的位置`:'先复习，再学新词 · 每 5 次练习为一组'}</p><button class="checkin-link" data-action="nav" data-id="stats">${completedDay(today())?icon('check'):icon('chart')} ${checkinStatus()}</button>${today().newTarget&&!completedDay(today())&&!newWords().length?'<p class="small-note">本轮已无新词，若要完成今日打卡，可在上方调整学习范围；已会跳过不计新词。</p>':''}</section>
  <section class="review-summary"><p>到期总量 ${dueWords().length} 词 · 待安排 ${backlog} 词</p>${backlog?`<button class="text-button" data-action="start" data-id="reviewExtra">额外复习 10 词</button>`:''}${backlog>state.reviewGoal*2?'<p class="small-note">积压较多，建议适当减少明天的新词，先巩固已学词。</p>':''}</section><section class="practice-section"><div class="section-title"><h2>专项练习</h2><span>按需要选择</span></div><div class="practice-grid"><button class="practice-card" data-action="start" data-id="new"><span class="practice-icon">${icon('leaf')}</span><strong>只学新词</strong><small>剩余 ${left} 词</small></button><button class="practice-card" data-action="start" data-id="review"><span class="practice-icon">${icon('chart')}</span><strong>到期复习</strong><small>${due} 词待复习</small></button><button class="practice-card" data-action="spell-start" data-id="spell"><span class="practice-icon">${icon('check')}</span><strong>拼写自测</strong><small>看释义 / 听音</small></button><button class="practice-card" data-action="weak-list"><span class="practice-icon warm">${icon('book')}</span><strong>错词强化</strong><small>${weakList.length} 词待强化</small></button></div></section>
  <section class="scope-progress"><div class="section-title"><h2>本轮进度</h2><span>${ps.learned+ps.known} / ${ps.total} 词</span></div><div class="progress-bar"><i style="width:${Math.round((ps.learned+ps.known)/ps.total*100)}%"></i></div><p>已学 ${ps.learned} · 已会跳过 ${ps.known} · 熟悉 ${ps.mastered}</p></section><p class="footer-note">${activeMode==='daily'?'按通用常用程度选词':'按通用常用程度选词，非真题频次排序'}</p></main>`);
}
function matches(w){const p=progress(w.w);return(!query||w.w.toLowerCase().includes(query.toLowerCase())||shortMeaning(w).includes(query))&&(tierFilter==='all'||w.tier===tierFilter||tierFilter==='plan'&&state.plan.ids.includes(w.w))&&(filter==='all'||filter==='star'&&p.star||filter==='new'&&!p.reps&&!p.known||filter==='learning'&&p.reps>0&&p.stage<4&&!p.known||filter==='mastered'&&(p.stage>=4||p.known)||filter==='weak'&&weak(p)&&!p.known);}
function filteredWords(){const list=(filter==='weak'||filter==='star'?WORDS:availableWords()).filter(matches);return filter==='weak'?list.sort(priority):list;}
function renderBook(){const list=filteredWords();shell(`<header class="page-heading"><p class="eyebrow">我的词库</p><h1>${filter==='weak'?'待强化':esc(collectionLabel())}<span class="dot">。</span></h1><p class="subtle">${filter==='weak'?'找到薄弱点，再练一次。':'先选范围，已会的词可以直接跳过。'}</p></header><main class="book-main"><label class="search-box">${icon('search')}<input id="search" type="search" placeholder="搜索单词或中文释义" value="${esc(query)}" aria-label="搜索单词或中文释义"></label><label class="tier-picker">学习范围<select id="tier-filter" aria-label="学习范围筛选">${[['all','整个词库'],['plan','当前计划'],...Object.entries(TIERS)].map(([id,label])=>`<option value="${id}" ${tierFilter===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="filters" aria-label="词条筛选">${[['all','全部'],['new','未学'],['learning','学习中'],['mastered','熟悉'],['star','收藏'],['weak','待强化']].map(([id,label])=>`<button data-action="filter" data-id="${id}" class="${filter===id?'selected':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>${filter==='weak'?`<div class="weak-actions"><button class="secondary tint" data-action="start" data-id="meaningWeak">复习词义 (${weakWords().filter(w=>progress(w.w).meaningWeak).length})</button><button class="secondary tint" data-action="spell-start" data-id="spellingWeak">练拼写 (${weakWords().filter(w=>progress(w.w).spellWeak).length})</button></div><p class="small-note">两种薄弱点分别记录；不同日期独立答对两次后解除强化。</p>`:''}<div class="list-heading"><span id="result-count">${list.length} 个词条</span>${filter==='star'?'<button class="text-button" data-action="start" data-id="favorites">练习收藏</button>':'<button class="text-button" data-action="frequency-info">分层依据</button>'}</div><div id="word-list">${wordList(list)}</div></main>`);}
function wordList(list){return list.length?`${list.slice(0,limit).map(w=>{const p=progress(w.w);return`<button class="word-row" data-action="detail" data-id="${esc(w.w)}"><div><strong>${esc(w.w)} <small class="tier-label">${TIERS[w.tier]}</small></strong><span>${esc(shortMeaning(w))}</span>${filter==='weak'?`<em>${p.meaningWeak?'词义需强化 ':''}${p.spellWeak?'拼写需强化 ':''} · 词义忘记 ${p.lapses} 次 / 拼写未答对 ${p.spellErrors} 次${p.mistakeAt?' · 最近 '+dayKey(new Date(p.mistakeAt)):''}</em>`:''}</div><span class="word-status ${p.known||p.stage>=4?'green':''}">${p.star?icon('star'):p.known?'已会':p.stage>=4?'熟悉':p.reps?'学习中':'未学'}</span></button>`;}).join('')}${list.length>limit?'<button class="load-more" data-action="more">加载更多单词</button>':''}`:'<div class="empty">暂时没有匹配的单词。</div>';}
function renderStats(){const ps=planStats(),pct=Math.round((ps.learned+ps.known)/ps.total*100),dates=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const h=state.history[dayKey(d)];dates.push({label:i===0?'今天':`${d.getMonth()+1}/${d.getDate()}`,n:h?h.words.length:0});}const max=Math.max(5,...dates.map(d=>d.n));shell(`<header class="page-heading"><p class="eyebrow">学习记录</p><h1>我的</h1><p class="subtle">每轮有范围，每天有进展。</p></header><main class="stats-main"><section class="progress-panel"><div class="section-title"><h2>${ROUTES[state.plan.route]} · ${ps.total} 词</h2><strong>${pct}%</strong></div><div class="progress-bar"><i style="width:${pct}%"></i></div><p class="subtle">已学 ${ps.learned} 词 · 已会跳过 ${ps.known} 词</p><div class="three-stats"><div><strong>${ps.mastered}</strong><span>范围内熟悉</span></div><div><strong>${weakWords().length}</strong><span>全部待强化</span></div><div><strong>${ps.known}</strong><span>已会跳过</span></div></div></section>${checkinHtml()}<section class="week-panel"><div class="section-title"><h2>最近 7 天</h2><span>词义与拼写去重计数</span></div><div class="bars">${dates.map(d=>`<div class="bar-item"><strong>${d.n}</strong><div class="bar-track"><i style="height:${Math.max(d.n?4:0,Math.round(d.n/max*100))}%"></i></div><span>${d.label}</span></div>`).join('')}</div><p class="small-note">今日拼写 ${today().spellAttempts} 次，独立答对 ${today().spellCorrect} 次</p></section><section class="settings"><h2>学习设置</h2><button class="setting-row" data-action="mode"><div><strong>学习模式 · ${BOOKS[activeMode].label}</strong><span>切换四级、六级或日常学习</span></div>${icon('arrow')}</button>${activeMode==='cet6'?`<button class="setting-row" data-action="collections"><div><strong>六级学习词库</strong><span>${esc(collectionLabel())} · 切换自动匹配已学记录</span></div>${icon('book')}</button>`:''}<button class="setting-row" data-action="plan"><div><strong>调整学习路线</strong><span>范围、备考天数、每天投入时间</span></div>${icon('arrow')}</button><label class="setting-row"><div><strong>每天的新词目标</strong><span>当天开始新词学习后锁定，修改次日生效</span></div><select id="goal" aria-label="每天的新词目标">${goalOptions(state.goal)}</select></label><label class="setting-row"><div><strong>每天的复习额度</strong><span>新一轮生效，未完成的位置保留</span></div><select id="review-goal" aria-label="每天的复习额度">${goalOptions(state.reviewGoal)}</select></label><button class="setting-row" data-action="update"><div><strong>检查应用更新</strong><span>App 内更新 / 下载新版 APK</span></div>${icon('download')}</button><button class="setting-row" data-action="export"><div><strong>备份学习进度</strong><span>所有模式的计划、错词和位置一起保存</span></div>${icon('download')}</button><button class="setting-row" data-action="import"><div><strong>恢复进度备份</strong><span>兼容旧版备份，导入前确认覆盖</span></div>${icon('upload')}</button><button class="setting-row" data-action="about"><div><strong>关于词芽与词库</strong><span>版本 1.3.3 · ${Object.keys(EXAMPLES).length} 词有自编例句</span></div>${icon('arrow')}</button></section><p class="footer-note">词义熟悉程度和拼写能力分别记录。</p></main>`);}
function shortMeaning(w){return MEANINGS[w.w];}
function exampleHtml(w){const e=EXAMPLES[w.w];if(!e)return'<p class="example-missing">本词暂未配例句。</p>';const re=new RegExp('\\b'+w.w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','ig');return`<section class="example"><span class="eyebrow">例句 · 应用自编</span><p class="example-en">${esc(e.en).replace(re,m=>`<mark>${m}</mark>`)}</p><details><summary>查看例句翻译</summary><p>${esc(e.zh)}</p></details></section>`;}
function wordBody(w,shown){const p=progress(w.w);return`<div class="word-tools"><span class="tag">${TIERS[w.tier]} · ${p.known?'已会':p.reps?'复习词':'新词'}</span><button class="icon-button ${p.star?'starred':''}" data-action="star" data-id="${esc(w.w)}" aria-label="${p.star?'取消收藏':'收藏单词'}" aria-pressed="${p.star}">${icon('star')}</button></div><div class="word-heading"><h2>${esc(w.w)}</h2><p class="phonetic">${w.p?`/${esc(w.p)}/`:'音标暂缺'} <button class="icon-button" data-action="speak" data-id="${esc(w.w)}" aria-label="播放 ${esc(w.w)} 的发音">${icon('sound')}</button></p></div>${shown?`<div class="definition"><span class="eyebrow">主要释义</span><p>${esc(shortMeaning(w))}</p>${exampleHtml(w)}</div>`:`<div class="recall-prompt"><p>你记得它的意思吗？</p><span>想一想，再查看释义</span></div>`}`;}
const emptySpell=()=>({answer:'',entered:'',hint:false,checked:false,correct:false});
function session(kind,mode,queue){return{kind,mode,queue:queue.map(w=>typeof w==='string'?w:w.w),index:0,revealed:false,initial:queue.map(w=>typeof w==='string'?w:w.w),groupWords:[],groupCount:0,pause:'',elapsedMs:0,budgetAt:state.plan.minutes*60000,retries:{},prompt:'meaning',spell:emptySpell(),returnCards:null};}
function accountTime(at){if(!study||!tick)return;study.elapsedMs+=Math.max(0,at-tick);let from=tick;while(from<at){const d=new Date(from),key=dayKey(d);d.setHours(24,0,0,0);const end=Math.min(at,d.getTime());if(!own(state.history,key))state.history[key]=emptyHistory();state.history[key].activeMs+=end-from;from=end;}tick=0;}
function stopTick(){accountTime(Date.now());}
function startTick(){if(study&&!study.pause&&unfinished(study)&&!document.hidden&&!tick)tick=Date.now();}
function persistSession(){if(study)state.session=study;save();}
function openSession(s){study=s;state.session=s;if(s.kind==='cards')lockDailyTarget(s.queue.slice(s.index));page=s.kind==='spell'?'spell':'study';undoAction=null;tick=0;startTick();render();window.scrollTo(0,0);}
function startStudy(mode,replace=false){
  if(readFailed){toast('请先恢复进度备份，避免覆盖无法读取的原数据。');return;}
  if(unfinished(state.session)&&!replace){modal={type:'replace',kind:'cards',mode};renderModal();return;}
  let queue=mode==='new'?newWords().slice(0,remaining()):mode==='review'?plannedReviewWords():mode==='reviewExtra'?dueWords().slice(0,10):mode==='meaningWeak'?weakWords().filter(w=>progress(w.w).meaningWeak):mode==='favorites'?WORDS.filter(w=>progress(w.w).star&&!progress(w.w).known):[...plannedReviewWords(),...newWords().slice(0,remaining())];
  if(!queue.length){toast(['review','reviewExtra'].includes(mode)?'今日复习安排已完成；有积压时可在首页选择额外复习。':mode==='meaningWeak'?'目前没有需要强化词义的词。':mode==='favorites'?'收藏中暂时没有可练习的词。':'今日计划已完成，明天继续。');return;}
  stopTick();openSession(session('cards',mode,queue));persistSession();
}
function resumeSession(){if(!unfinished(state.session)){toast('暂时没有未完成的学习。');return;}openSession(state.session);persistSession();}
function checkpoint(){stopTick();study.index++;study.revealed=false;study.groupCount++;if(study.index<study.queue.length){if(today().activeMs>=(study.budgetAt||state.plan.minutes*60000))study.pause='time';else if(study.groupCount>=5)study.pause='group';}persistSession();startTick();render();window.scrollTo(0,0);}
function rememberUndo(word){stopTick();undoAction={word,had:own(state.words,word),progress:clone(progress(word)),date:dayKey(),hadHistory:own(state.history,dayKey()),history:clone(today()),session:clone(study)};startTick();}
function undo(){if(!undoAction)return;stopTick();const u=undoAction,activeMs=state.history[u.date]?state.history[u.date].activeMs:0;if(u.had)state.words[u.word]=u.progress;else delete state.words[u.word];state.history[u.date]=u.history;state.history[u.date].activeMs=activeMs;study=u.session;study.pause='';state.session=study;undoAction=null;tick=0;page=study.kind==='spell'?'spell':'study';persistSession();startTick();render();window.scrollTo(0,0);toast('已撤销上一次选择。');}
function recordPractice(word,isNew=false,spelling=false,correct=false){const key=dayKey();if(!own(state.history,key))state.history[key]=emptyHistory();if(isNew)lockDailyTarget([word]);const h=state.history[key],wasComplete=completedDay(h);if(!h.words.includes(word))h.words.push(word);if(isNew&&!h.new.includes(word))h.new.push(word);if(!isNew&&!spelling&&!h.new.includes(word)&&!h.reviewed.includes(word))h.reviewed.push(word);h.attempts++;if(spelling){h.spellAttempts++;if(correct)h.spellCorrect++;}if(!wasComplete&&completedDay(h))toast('今日新词任务完成，学习打卡已点亮。');}
function markWeak(p,type){p[type+'Weak']=true;p[type+'Wins']=0;p[type+'WinDay']='';p.mistakeAt=Date.now();}
function independentWin(p,type){if(p[type+'Weak']&&p[type+'WinDay']!==dayKey()){p[type+'Wins']=Math.min(2,p[type+'Wins']+1);p[type+'WinDay']=dayKey();if(p[type+'Wins']>=2)p[type+'Weak']=false;}}
function interval(p,rating){return rating==='hard'?1:[1,3,7,14,30,60][Math.min(p.stage,5)];}
function rate(rating){
  if(!study||study.kind!=='cards'||!study.revealed||!['again','hard','good'].includes(rating))return;
  const word=study.queue[study.index],p=clone(progress(word));rememberUndo(word);recordPractice(word,!p.reps);if(!p.reps)p.first=dayKey();
  if(rating==='again'){p.stage=0;p.due=Date.now()+10*60000;p.lapses++;markWeak(p,'meaning');const n=study.retries[word]||0;if(n<2){study.queue.push(word);study.retries[word]=n+1;}}
  else{p.due=Date.now()+interval(p,rating)*DAY;p.stage=rating==='hard'?Math.max(1,p.stage-1):Math.min(6,p.stage+1);if(rating==='hard')markWeak(p,'meaning');else independentWin(p,'meaning');}
  p.reps++;p.known=false;state.words[word]=p;if(!study.groupWords.includes(word))study.groupWords.push(word);checkpoint();
}
function skipKnown(word){
  if(!WORD_MAP.has(word))return;const p=clone(progress(word));
  if(study&&page==='study'){rememberUndo(word);p.known=true;p.meaningWeak=false;p.spellWeak=false;p.due=0;state.words[word]=p;if(['daily','new'].includes(study.mode)){const replacement=newWords().find(w=>!study.queue.includes(w.w));if(replacement){study.queue.push(replacement.w);study.initial.push(replacement.w);}}stopTick();study.index++;study.revealed=false;persistSession();startTick();render();window.scrollTo(0,0);}
  else{p.known=!p.known;if(p.known){p.meaningWeak=false;p.spellWeak=false;p.due=0;}state.words[word]=p;save();render();toast(p.known?'已标记为已会，不再占用新词额度。':'已放回学习队列。');}
}
function studyHeader(label){return`<header class="study-header"><button class="icon-button" data-action="leave" aria-label="退出学习">${icon('back')}</button><span>${label}</span><span>${study.index+1} / ${study.queue.length}</span></header>`;}
function undoButton(){return undoAction?'<button class="text-button undo-button" data-action="undo">撤销上一次选择</button>':'';}
function renderStudy(){
  if(!study||study.index>=study.queue.length){renderDone();return;}if(study.pause){renderBreak();return;}
  const w=WORD_MAP.get(study.queue[study.index]);shell(`${studyHeader(study.mode==='meaningWeak'?'词义强化':study.mode==='reviewExtra'?'额外复习':study.mode==='review'?'到期复习':study.mode==='favorites'?'收藏练习':study.mode==='new'?'新词学习':'今日学习')}<main class="study-main"><div class="progress-bar"><i style="width:${Math.round(study.index/study.queue.length*100)}%"></i></div><div class="study-controls"><span>先回想，再看释义</span><button class="text-button" data-action="known" data-id="${esc(w.w)}">这个词我已会，跳过</button></div><article class="word-card">${wordBody(w,study.revealed)}</article>${study.revealed?`<p class="rating-hint">按这次真实的记忆情况选择</p><div class="ratings"><button data-action="rate" data-id="again"><strong>忘记了</strong><span>稍后再练</span></button><button data-action="rate" data-id="hard"><strong>有点模糊</strong><span>1 天后</span></button><button data-action="rate" data-id="good"><strong>记住了</strong><span>${interval(progress(w.w),'good')} 天后</span></button></div>`:`<button class="primary" data-action="reveal">查看释义 ${icon('arrow')}</button>`}${undoButton()}<p class="footer-note">每 5 次练习可以休息或测拼写；学习位置自动保存。</p></main>`,false);
}
function renderBreak(){stopTick();persistSession();shell(`<main class="completion"><div class="completion-art">${icon('leaf')}</div><p class="eyebrow">练习小结</p><h1>${study.pause==='time'?'先休息一下。':'这一组，完成了。'}</h1><p class="subtle">${study.pause==='time'?`今日累计已达到你设置的 ${state.plan.minutes} 分钟学习时间。`:'已完成 5 次练习，可以用拼写检验一下。'}</p><div class="done-stats"><div><strong>${study.index}</strong><span>完成练习次数</span></div><div><strong>${study.queue.length-study.index}</strong><span>本轮剩余次数</span></div></div>${study.kind==='cards'&&study.groupWords.length?'<button class="primary" data-action="batch-spell">测一测这组的拼写</button>':''}<button class="${study.kind==='cards'?'secondary':'primary'}" data-action="continue">继续本轮学习</button><button class="secondary" data-action="home-pause">保存位置，回到今日</button>${undoButton()}</main>`,false);}
function renderDone(){stopTick();persistSession();const isSpell=study&&study.kind==='spell',weakSpell=isSpell?study.initial.filter(w=>progress(w).spellWeak&&!progress(w).known):[];shell(`<main class="completion"><div class="completion-art">${icon('leaf')}</div><p class="eyebrow">练习小结</p><h1>${isSpell?'这一轮拼写，完成了。':'这一轮学习，完成了。'}</h1><p class="subtle">${isSpell?'词义与拼写分别记录，继续巩固薄弱点。':'新词、复习词分别计数，反复练习也不会重复增加新词。'}</p><div class="done-stats"><div><strong>${today().new.length}</strong><span>今日新词</span></div><div><strong>${today().words.length}</strong><span>今日练习词</span></div><div><strong>${weakWords().length}</strong><span>待强化</span></div></div>${isSpell&&weakSpell.length?`<button class="secondary tint" data-action="retry-spell">只练本轮薄弱拼写 (${weakSpell.length})</button>`:''}${isSpell&&study.returnCards?'<button class="primary" data-action="return-cards">回到词义学习</button>':!isSpell&&study.groupWords.length?'<button class="primary" data-action="batch-spell">测一测这组的拼写</button>':''}<button class="${isSpell&&study.returnCards||!isSpell&&study.groupWords.length?'secondary':'primary'}" data-action="finish">回到今日</button>${undoButton()}<p class="footer-note">尚未解除的薄弱点，可在「待强化」中集中练习。</p></main>`,false);}
const normalize=s=>s.trim().toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ');
const variantGroups=[['centre','center'],['colour','color'],['favour','favor'],['honour','honor'],['labour','labor'],['behaviour','behavior'],['neighbour','neighbor'],['analyse','analyze'],['organise','organize'],['recognise','recognize'],['realise','realize'],['apologise','apologize'],['defence','defense'],['licence','license'],['travelling','traveling'],['cancelled','canceled']];
function accepted(word,answer){const w=normalize(word),a=normalize(answer);return w===a||variantGroups.some(g=>g.includes(w)&&g.includes(a));}
function spellingDiff(expected,input){
  const a=normalize(expected),b=normalize(input),dp=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));
  for(let i=0;i<=a.length;i++)dp[i][0]=i;for(let j=0;j<=b.length;j++)dp[0][j]=j;
  for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+Number(a[i-1]!==b[j-1]));
  const parts=[];let i=a.length,j=b.length;
  while(i||j){if(i&&j&&a[i-1]===b[j-1]){parts.push(esc(a[--i]));j--;}else if(i&&j&&dp[i][j]===dp[i-1][j-1]+1){parts.push(`<mark class="diff-wrong">${esc(a[--i])}</mark>`);j--;}else if(i&&dp[i][j]===dp[i-1][j]+1){parts.push(`<mark class="diff-missing">${esc(a[--i])}</mark>`);}else{parts.push(`<del class="diff-extra">${esc(b[--j])}</del>`);}}
  return parts.reverse().join('');
}
function startSpelling(mode='spell',replace=false){
  if(readFailed){toast('请先恢复有效备份。');return;}
  if(unfinished(state.session)&&!replace){modal={type:'replace',kind:'spell',mode};renderModal();return;}
  const list=mode==='spellingWeak'?weakWords().filter(w=>progress(w.w).spellWeak):pool().filter(w=>progress(w.w).reps>0&&!progress(w.w).known).sort(priority);
  if(!list.length){toast(mode==='spellingWeak'?'暂时没有拼写薄弱词。':'先学几个单词，再来测试拼写。');return;}
  stopTick();openSession(session('spell',mode,list.slice(0,20)));persistSession();
}
function batchSpelling(){if(!study||study.kind!=='cards'||!study.groupWords.length)return;stopTick();const cards=clone(study),s=session('spell','batch',study.groupWords.slice(-5));s.returnCards=cards;openSession(s);persistSession();}
function retrySpelling(){if(!study||study.kind!=='spell'||unfinished(study))return;const queue=study.initial.filter(w=>progress(w).spellWeak&&!progress(w).known);if(!queue.length)return;stopTick();const s=session('spell','batch',queue);s.returnCards=study.returnCards?clone(study.returnCards):null;s.prompt=study.prompt;openSession(s);persistSession();}
function checkSpelling(showAnswer=false){
  if(!study||study.kind!=='spell'||study.spell.checked)return;const word=study.queue[study.index],sp=study.spell;
  if(!showAnswer&&!sp.answer.trim()){toast('先输入你的答案，再提交。');return;}
  rememberUndo(word);const p=clone(progress(word));if(showAnswer)sp.hint=true;sp.entered=sp.answer;sp.correct=!showAnswer&&accepted(word,sp.answer);sp.checked=true;
  const independentlyCorrect=sp.correct&&!sp.hint;recordPractice(word,false,true,independentlyCorrect);p.spellAttempts++;
  if(!independentlyCorrect){markWeak(p,'spell');p.known=false;if(!sp.correct)p.spellErrors++;}else independentWin(p,'spell');
  state.words[word]=p;stopTick();persistSession();startTick();renderSpelling();
}
function nextSpelling(){if(!study||!study.spell.checked)return;study.spell=emptySpell();checkpoint();}
function renderSpelling(){
  if(!study||study.index>=study.queue.length){renderDone();return;}if(study.pause){renderBreak();return;}
  const word=study.queue[study.index],w=WORD_MAP.get(word),sp=study.spell;
  shell(`${studyHeader(study.mode==='spellingWeak'?'拼写强化':'拼写自测')}<main class="study-main spelling-main"><div class="progress-bar"><i style="width:${Math.round(study.index/study.queue.length*100)}%"></i></div><div class="spell-mode"><button data-action="spell-mode" data-id="meaning" class="${study.prompt==='meaning'?'selected':''}" ${sp.checked?'disabled':''}>看释义拼写</button><button data-action="spell-mode" data-id="listen" class="${study.prompt==='listen'?'selected':''}" ${sp.checked?'disabled':''}>听音拼写</button></div><article class="spell-card"><p class="eyebrow">${TIERS[w.tier]} · ${study.prompt==='meaning'?'回忆英文':'听一听，再写下来'}</p><h2>写出这个单词</h2>${study.prompt==='meaning'?`<p class="spell-meaning">${esc(shortMeaning(w))}</p>`:`<button class="listen-button" data-action="speak" data-id="${esc(word)}" aria-label="播放待拼写单词的发音">${icon('sound')} 播放发音</button><p class="small-note">无英语语音包时，可切换到看释义拼写。</p>`}<form id="spell-form"><label for="spell-input" class="sr-only">英文拼写</label><input id="spell-input" type="text" inputmode="text" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" maxlength="100" placeholder="输入英文单词" value="${esc(sp.answer)}" ${sp.checked?'readonly':''}><p class="spell-hint">${sp.hint?`首字母：${esc(word[0])} · 参考长度 ${word.length} 个字符`:`参考长度：${word.length} 个字符 · 本题练习这轮学过的目标词。`}</p>${!sp.checked?'<button class="primary" type="submit">提交拼写</button>':''}</form>${!sp.checked?'<div class="spell-help"><button class="text-button" data-action="spell-hint">首字母提示</button><button class="text-button" data-action="spell-answer">查看答案</button></div>':`<section class="spell-result ${sp.correct&&!sp.hint?'success':'needs-work'}" role="status"><strong>${sp.correct?sp.hint?'答对了，再独立拼一次':'独立拼写正确':'记住这个写法，再试一次'}</strong><p class="answer-word">${esc(word)}</p>${!sp.correct?`<p>你的输入：${esc(sp.entered)||'未输入'}</p><div class="letter-diff">${spellingDiff(word,sp.entered)}</div><p class="small-note">红色：写错 · 虚线：漏写 · 划掉：多写</p>`:normalize(sp.entered)!==normalize(word)?'<p class="small-note">已接受对应的英美拼写变体。</p>':''}<p>${esc(shortMeaning(w))}</p></section>`}</article>${sp.checked?`<button class="primary" data-action="spell-next">${study.index+1<study.queue.length?'下一个单词':'完成本轮拼写'} ${icon('arrow')}</button>`:''}${undoButton()}<p class="footer-note">使用提示或查看答案的词会保留在拼写强化队列。</p></main>`,false);
}
function openPlan(){const p=state.planChosen?clone(state.plan):Object.assign(completePlan(),{route:'focus',size:Math.min(300,availableWords().length)});modal={type:'plan',draft:p};renderModal();}
function planInput(){const form=document.getElementById('plan-form');if(!form)return null;return{route:form.elements.route.value,size:Number(form.elements.size.value),days:Number(form.elements.days.value),minutes:Number(form.elements.minutes.value),goal:Number(form.elements.dailyGoal.value),tiers:[...form.querySelectorAll('input[name="tiers"]:checked')].map(x=>x.value),source:form.elements.source.value};}
function candidates(p){if(p.route==='complete')return availableWords();return availableWords().filter(w=>!progress(w.w).known&&(p.route!=='custom'||p.tiers.includes(w.tier))&&(p.route!=='custom'||p.source==='all'||p.source==='star'&&progress(w.w).star||p.source==='weak'&&weak(progress(w.w)))).slice(0,p.size);}
function updatePlanPreview(){const p=planInput();if(!p)return;document.getElementById('scope-fields').hidden=p.route==='complete';document.getElementById('custom-fields').hidden=p.route!=='custom';const list=candidates(p),unlearned=list.filter(w=>!progress(w.w).reps&&!progress(w.w).known).length,days=int(p.goal,5,100)?Math.ceil(unlearned/p.goal):0;document.getElementById('plan-preview').innerHTML=`<strong>本轮 ${list.length} 词 · 未学 ${unlearned} 词</strong><p>${days?`按每天 ${p.goal} 个新词，首次覆盖约 ${days} 天。`:'这个范围没有未学词，可以继续复习。'}${days>p.days?'已超出所选天数，建议缩小范围或调整目标。':''}</p><span>估算不含复习；今日累计达到所选分钟数后会提醒休息。通用词频不代表真题频次。</span>`;}
function applyPlan(){const form=document.getElementById('plan-form');if(!form.reportValidity())return;const p=planInput();if(!int(p.goal,5,100)||!int(p.days,1,365)||!int(p.minutes,5,120)||!p.tiers.length){toast('请填写有效的计划，并至少选择一层词汇。');return;}const list=candidates(p);if(!list.length){toast('这个范围暂时没有词，请换一个范围。');return;}stopTick();state.plan={route:p.route,size:p.route==='complete'?availableWords().length:p.size,days:p.days,minutes:p.minutes,tiers:p.tiers,source:p.route==='custom'?p.source:'all',ids:list.map(w=>w.w),created:dayKey()};state.goal=p.goal;state.planChosen=true;state.session=null;study=null;undoAction=null;modal=null;page='home';save();render();window.scrollTo(0,0);toast('学习范围已更新，已有记录保留；已锁定的今日目标保持不变。');}
function planForm(){const p=modal.draft;return`<div class="plan-dialog"><p class="eyebrow">MAKE ROOM FOR WHAT MATTERS</p><h2>选一条学习路线</h2><form id="plan-form"><label class="form-field">学习路线<select name="route" aria-label="学习路线">${Object.entries(ROUTES).map(([id,label])=>`<option value="${id}" ${p.route===id?'selected':''}>${label}</option>`).join('')}</select></label><div id="scope-fields"><label class="form-field">本轮范围上限<select name="size" aria-label="本轮范围上限">${[...new Set([100,300,600,1000,1500,3500,availableWords().length])].filter(n=>n<=availableWords().length).map(n=>`<option value="${n}" ${p.size===n?'selected':''}>${n===availableWords().length?'整个可选范围':n+' 词'}</option>`).join('')}</select></label><p class="small-note">按通用语料参考顺序选词，已会词会跳过。保存后范围固定，进度更容易看清。</p></div><div id="custom-fields"><fieldset><legend>选择词汇层级</legend>${Object.entries(TIERS).map(([id,label])=>`<label class="check-label"><input type="checkbox" name="tiers" value="${id}" ${p.tiers.includes(id)&&WORDS.some(w=>w.tier===id)?'checked':''} ${WORDS.some(w=>w.tier===id)?'':'disabled'}>${label} · ${WORDS.filter(w=>w.tier===id).length} 词</label>`).join('')}</fieldset><label class="form-field">词条来源<select name="source" aria-label="词条来源">${[['all','所选层级中的全部词'],['star','所选层级中的收藏词'],['weak','所选层级中的薄弱词']].map(([id,label])=>`<option value="${id}" ${p.source===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="form-grid"><label class="form-field">备考天数<input name="days" type="number" min="1" max="365" required value="${p.days}" aria-label="备考天数"></label><label class="form-field">每天投入（分钟）<input name="minutes" type="number" min="5" max="120" required value="${p.minutes}" aria-label="每天投入分钟"></label></div><label class="form-field">每日新词目标<select name="dailyGoal" aria-label="计划每日新词目标">${goalOptions(state.goal)}</select></label><div id="plan-preview" class="plan-preview" aria-live="polite"></div><p class="small-note">调整计划保留全部已学记录；未完成的本轮位置会结束。再次开始会按新范围选词。今日打卡目标已锁定时，修改每日目标从明天生效。</p><button class="primary" type="submit">保存学习计划 ${icon('check')}</button></form></div>`;}
