window.receiveUpdate=u=>{updateInfo=u;if(modal&&modal.type==='update')renderModal();else if(['available','ready'].includes(u.status))toast(u.status==='ready'?'新版已下载，请在「我的 → 检查应用更新」确认安装。':'有新版可用，请在「我的 → 检查应用更新」查看。');};
