function collectionsHtml(){const c=state.collection,stats=ids=>{const list=ids.map(w=>progress(w));return '已学 '+list.filter(p=>p.reps&&!p.known).length+' · 已会 '+list.filter(p=>p.known).length;};return `<div class="confirm-content"><h2>选择六级词库</h2><p>重合单词共用学习记录、复习时间、错词和收藏。</p><button class="mode-option" data-action="collection-select" data-id="base"><span><strong>六级完整词库${state.activeList==='base'?' · 当前':''}</strong><small>${BOOKS.cet6.words.length} 词 · ${stats(BOOKS.cet6.words.map(w=>w.w))}</small></span></button>${c?`<button class="mode-option" data-action="collection-select" data-id="custom"><span><strong>${esc(c.name)}${state.activeList==='custom'?' · 当前':''}</strong><small>${c.ids.length} 词 · ${stats(c.ids)}</small></span></button><details><summary>查看词表来源</summary><p class="small-note">${esc(c.source)||'导入文件未填写来源'}</p></details>`:''}<button class="secondary" data-action="collection-file">导入本机词表</button><p class="small-note">支持词芽 JSON 词表。切换会结束未完成的本轮位置；已学记录、当日新词目标、复习额度和打卡保留。不在当前词库的旧词也会保留。</p></div>`;}
window.receiveWordlist=raw=>{try{
 if(readFailed||activeMode!=='cet6')throw Error('请先切换六级并恢复有效进度');
 if(typeof raw!=='string'||raw.length>3000000)throw Error('词表过大');
 const data=JSON.parse(raw.replace(/^\uFEFF/,''));if(data.format!=='wordleaf-wordlist-v1'||typeof data.name!=='string'||!data.name.trim()||data.name.length>40||typeof data.source!=='string'||data.source.length>1000||!Array.isArray(data.entries)||!data.entries.length||data.entries.length>10000)throw Error('不是有效的词芽词表');
 const baseMap=new Map(WORDS.filter(w=>! /^[A-Z]{2,}$/.test(w.w)).map(w=>[w.w.toLowerCase(),w.w])),entries=new Map(state.customEntries.map(e=>[e.word,e])),ids=[];
 for(const e of data.entries){if(!e||typeof e.word!=='string')throw Error('词条异常');const key=e.word.trim().toLowerCase();if(!/^[a-z][a-z '-]*$/.test(key)||key.length>80)throw Error('单词拼写异常');const word=WORD_MAP.has(e.word.trim())?e.word.trim():baseMap.get(key)||key;if(!WORD_MAP.has(word)){if(typeof e.meaning!=='string'||!/[\u3400-\u9fff]/.test(e.meaning)||e.meaning.length>180||typeof e.phonetic!=='string'||e.phonetic.length>100)throw Error('新增词缺少有效中文释义或音标');entries.set(word,{word,phonetic:e.phonetic,meaning:e.meaning});}if(!ids.includes(word))ids.push(word);}
 const draft={...state,customEntries:[...entries.values()],collection:{name:data.name.trim(),source:data.source,ids},activeList:'custom'};cleanUserData(draft);if(JSON.stringify(draft).length>5000000)throw Error('进度容量不足');modal={type:'collection-import',draft};renderModal();
 }catch(e){toast('无法导入：'+e.message+'。原进度未改变。');}};
function collectionPreview(){const c=modal.draft.collection,list=c.ids.map(w=>progress(w));return `<div class="confirm-content"><h2>导入 ${esc(c.name)}</h2><p>共 ${c.ids.length} 词 · 已学 ${list.filter(p=>p.reps&&!p.known).length} · 已会 ${list.filter(p=>p.known).length} · 未学 ${list.filter(p=>!p.reps&&!p.known).length}</p><p class="small-note">${esc(c.source)}</p><p>导入后切换到此词库，重合单词自动沿用六级记录。原有记录保留，未完成的本轮位置会结束，当天目标保持不变。</p><button class="primary" data-action="collection-confirm">确认导入并切换</button><button class="secondary" data-action="close">暂不导入</button></div>`;}
