function applyCollectionImport(){if(!modal||modal.type!=='collection-import')return;stopTick();state.collectionPlans[state.activeList]=clone(state.plan);const d=modal.draft;delete state.collectionPlans.custom;state.customEntries=d.customEntries;state.collection=d.collection;state.activeList='custom';useBook(activeMode,state);resetCollectionPlan();toast('词库已导入，已有学习记录自动匹配。');}
function selectCollection(id){if(readFailed||activeMode!=='cet6'||!['base','custom'].includes(id)||id==='custom'&&!state.collection)return;if(state.activeList===id){closeModal();return;}stopTick();state.collectionPlans[state.activeList]=clone(state.plan);state.activeList=id;resetCollectionPlan();toast('词库已切换，已学记录与今日目标保留。');}
function aboutHtml(){const counts=tierCounts();return`<div class="about"><img src="leaf.svg" alt=""><h2>词芽 1.3.3</h2><p>当前模式：${BOOKS[activeMode].label}</p><h3>词库与分层</h3><p>${esc(BOOKS[activeMode].description)} 共 ${WORDS.length} 词：常用层 ${counts.common} 词，进阶层 ${counts.intermediate} 词，拓展层 ${counts.extended} 词。</p><p>顺序参考词典中的通用语料词频：优先 BNC，缺失时参考 FRQ。分层边界由应用设定，不是真题频次、官方词表或考试覆盖率。日常模式为通用常用词积累，暂不包含生活场景课程。</p><h3>中文释义与例句</h3><p>只显示精简中文主要义，不展示英文释义或完整义项。六级前 300 个参考顺位词及例句词的主要义已核对；新增词库复用已有主要义，其他义项依据原词库精简。这里的主要义不代表已统计验证的考试高频义。</p><p>当前词库有 ${Object.keys(EXAMPLES).length} 个词配有应用自编例句与翻译，不是真题原句。没有例句的词会明确提示，暂不继续扩充。</p><h3>复习与错词</h3><p>「记住了」依次间隔 1、3、7、14、30、60 天；「有点模糊」1 天后复习并降低熟悉程度；「忘记了」10 分钟后到期，本轮最多再练两次。词义与拼写分别在两个不同日期独立答对后解除强化；同日多次答对只计一次。</p><p>提示或查看答案不算独立拼写正确，拼写不会提高词义熟悉程度或占用新词额度。已会跳过的词可在详情中重新加入。</p><h3>学习打卡</h3><p>完成当日新词任务后自动打卡。当天开始新词学习时锁定目标，修改每日目标从次日生效；计划内剩余新词少于设置目标时，按开始时可学的新词数安排。已会跳过、单纯复习或拼写不代替新词任务。</p><p>各模式独立完成目标，任一模式达标即记录一天，同一天只计一次。累计、连续和最长连续天数按达标日期计算。旧版没有每日目标记录，因此保留旧练习记录，不推算历史打卡。</p><h3>模式与进度</h3><p>各模式独立保存计划、学习进度、收藏、错词和未完成位置，词义与拼写统计反映当前模式，打卡天数合并各模式的达标日期。切换回来可继续学习；同一个词在不同模式中分别记录。</p><p>备份包含所有已使用模式，可读取 1.0、1.1 的六级备份。恢复会覆盖所有模式的记录，新版备份不能用于旧版。卸载会删除本机进度，请先导出备份。</p><h3>时间与发音</h3><p>覆盖天数为首次学习的估算，不含复习或遗忘。后台和主动暂停的时间不计入；达到每日时间目标后会在当前词完成时提醒休息。</p><p>发音使用手机系统的英语语音，离线发音需要安装英语语音包。页面已禁用双指缩放，保留正常滚动。</p><h3>ECDICT · MIT 许可</h3><pre>${esc(window.WORDLEAF_LICENSE)}</pre></div>`;}
function renderModal(){
  const root=document.getElementById('modal-root');if(!root||!modal)return;document.body.style.overflow='hidden';let content='';
  if(modal.type==='plan')content=planForm();
  else if(modal.type==='collections')content=collectionsHtml();
  else if(modal.type==='collection-import')content=collectionPreview();
  else if(modal.type==='mode')content=`<div class="mode-dialog"><p class="eyebrow">CHOOSE YOUR WORDS</p><h2>选择学习模式</h2><p class="subtle">每个模式分别保存计划、进度和学习位置，随时可以切回来。</p><div class="mode-list">${Object.entries(BOOKS).map(([id,b])=>`<button class="mode-option ${id===activeMode?'selected':''}" data-action="switch-mode" data-id="${id}" aria-pressed="${id===activeMode}"><span><strong>${b.label}</strong><small>${esc(b.description)}</small><em>${b.words.length.toLocaleString()} 词${library.books[id]?' · 已有学习记录':''}</em></span>${id===activeMode?icon('check'):icon('arrow')}</button>`).join('')}</div><p class="small-note">日常学习先提供通用常用词积累，暂不包含按生活场景整理的课程。</p></div>`;
  else if(modal.type==='word'){const w=WORD_MAP.get(modal.word),p=progress(w.w);content=`<article class="word-card detail-card">${wordBody(w,true)}<p class="small-note">${TIERS[w.tier]} · 本词库参考顺位 ${w.order}${w.f?' · '+w.basis+' 语料位次 '+w.f:' · 语料位次缺失'}</p><button class="secondary tint" data-action="known" data-id="${esc(w.w)}">${p.known?'重新加入学习':'这个词我已会，跳过'}</button></article>`;}
  else if(modal.type==='update')content=updateHtml();
  else if(modal.type==='about')content=aboutHtml();
  else if(modal.type==='frequency')content=`<div class="confirm-content"><h2>通用常用程度</h2><p>当前 ${BOOKS[activeMode].label} 词库按通用语料参考顺序分层：常用层 ${tierCounts().common} 词，进阶层 ${tierCounts().intermediate} 词，拓展层 ${tierCounts().extended} 词。缺失 BNC 位次时参考 FRQ；两种语料的位次仅作为选词参考。</p><p>这是应用设定的学习范围，不是真题出现频次。词频高，也不意味着你还没掌握。</p><button class="primary" data-action="close">明白了</button></div>`;
  else if(modal.type==='leave')content=`<div class="confirm-content"><h2>先休息一下？</h2><p>已完成的词和当前学习位置都会保留。回来后从这里继续。</p><button class="primary" data-action="home-pause">保存位置，回到今日</button><button class="secondary" data-action="close">继续学习</button></div>`;
  else if(modal.type==='replace')content=`<div class="confirm-content"><h2>开始另一轮练习？</h2><p>已有完成记录会保留；上次未完成的位置将由这轮新练习替换。</p><button class="primary" data-action="replace-session">开始新练习</button><button class="secondary" data-action="resume-existing">继续上次学习</button></div>`;
  else if(modal.type==='restore')content=`<div class="confirm-content"><h2>恢复这份备份？</h2><p>备份包含 ${Object.keys(modal.data.books).length} 个模式的记录，打开后为 ${BOOKS[modal.data.activeMode].label}。恢复会覆盖所有模式的计划、进度、收藏和未完成位置。</p><button class="primary" data-action="restore">确认恢复</button><button class="secondary" data-action="close">保留当前进度</button></div>`;
  root.innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${modal.type==='mode'?'选择学习模式':modal.type==='plan'?'学习路线设置':modal.type==='word'?'单词详情':'操作说明'}"><button class="icon-button modal-close" data-action="close" aria-label="关闭">${icon('close')}</button>${content}</section></div>`;root.querySelector('.modal-close').focus();if(modal.type==='plan')updatePlanPreview();
}
function closeModal(){modal=null;document.body.style.overflow='';const root=document.getElementById('modal-root');if(root)root.innerHTML='';}
function speak(word){if(window.Android){Android.speak(word);return;}if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(word);u.lang='en-US';u.rate=.85;u.onerror=()=>toast('当前设备没有可用的英语语音。');speechSynthesis.cancel();speechSynthesis.speak(u);}else toast('当前设备不支持语音朗读。');}
function exportBackup(){stopTick();persistSession();const data=readFailed?(window.Android?Android.getState():localStorage.getItem('wordleaf-state')):JSON.stringify(snapshotLibrary(),null,2);if(window.Android){Android.exportBackup(data);startTick();return;}const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`wordleaf-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份文件已准备好。');startTick();}
window.receiveBackup=raw=>{try{modal={type:'restore',data:validateLibrary(JSON.parse(raw))};renderModal();}catch(e){toast('无法导入：这不是有效的词芽进度备份。');}};
window.appBack=()=>{if(modal){closeModal();return true;}if(page==='study'||page==='spell'){modal={type:'leave'};renderModal();return true;}if(page!=='home'){page='home';render();return true;}return false;};
function pauseHome(){stopTick();persistSession();modal=null;page='home';render();window.scrollTo(0,0);}
document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const{action,id}=el.dataset;
  if(action==='nav'){stopTick();persistSession();modal=null;page=id;render();window.scrollTo(0,0);}
  else if(action==='plan')openPlan();
  else if(action==='collections'){modal={type:'collections'};renderModal();}
  else if(action==='collection-file'){if(window.Android)Android.importWordlist();else document.getElementById('wordlist-file').click();}
  else if(action==='collection-select')selectCollection(id);
  else if(action==='collection-confirm')applyCollectionImport();
  else if(action==='mode'){snapshotLibrary();modal={type:'mode'};renderModal();}
  else if(action==='switch-mode')switchMode(id);
  else if(action==='start')startStudy(id);
  else if(action==='resume')resumeSession();
  else if(action==='reveal'){if(study){study.revealed=true;persistSession();renderStudy();}}
  else if(action==='rate')rate(id);
  else if(action==='known')skipKnown(id);
  else if(action==='undo')undo();
  else if(action==='speak')speak(id);
  else if(action==='star'){const p=clone(progress(id));p.star=!p.star;state.words[id]=p;save();render();}
  else if(action==='detail'){modal={type:'word',word:id};renderModal();}
  else if(action==='close')closeModal();
  else if(action==='filter'){filter=id;limit=50;renderBook();}
  else if(action==='more'){limit+=50;document.getElementById('word-list').innerHTML=wordList(filteredWords());}
  else if(action==='weak-list'){page='book';filter='weak';tierFilter='all';query='';limit=50;render();window.scrollTo(0,0);}
  else if(action==='frequency-info'){modal={type:'frequency'};renderModal();}
  else if(action==='leave'){modal={type:'leave'};renderModal();}
  else if(action==='home-pause')pauseHome();
  else if(action==='continue'){if(study.pause==='time')study.budgetAt=today().activeMs+state.plan.minutes*60000;study.pause='';study.groupCount=0;study.groupWords=[];persistSession();startTick();render();window.scrollTo(0,0);}
  else if(action==='spell-start')startSpelling(id);
  else if(action==='batch-spell')batchSpelling();
  else if(action==='retry-spell')retrySpelling();
  else if(action==='spell-mode'){if(study&&!study.spell.checked){study.prompt=id;persistSession();renderSpelling();}}
  else if(action==='spell-hint'){study.spell.hint=true;persistSession();renderSpelling();}
  else if(action==='spell-answer')checkSpelling(true);
  else if(action==='spell-next')nextSpelling();
  else if(action==='return-cards'){if(study.returnCards){const s=study.returnCards;stopTick();s.groupCount=0;s.groupWords=[];if(s.pause==='time')s.budgetAt=today().activeMs+state.plan.minutes*60000;s.pause='';openSession(s);persistSession();}}
  else if(action==='finish'){stopTick();if(study&&study.returnCards&&unfinished(study.returnCards))state.session=study.returnCards;else state.session=null;study=null;undoAction=null;modal=null;page='home';save();render();window.scrollTo(0,0);}
  else if(action==='replace-session'){const m=modal;modal=null;m.kind==='spell'?startSpelling(m.mode,true):startStudy(m.mode,true);}
  else if(action==='resume-existing'){closeModal();resumeSession();}
  else if(action==='calendar-prev'){calendarOffset++;renderStats();}
  else if(action==='calendar-next'){calendarOffset=Math.max(0,calendarOffset-1);renderStats();}
  else if(action==='update'){modal={type:'update'};renderModal();if(window.Android)Android.checkUpdate(true);}
  else if(action==='update-check'){if(window.Android)Android.checkUpdate(true);else toast('请在安卓版中检查更新。');}
  else if(action==='update-download'){if(window.Android)Android.downloadUpdate();else toast('请在安卓版中使用 App 内更新。');}
  else if(action==='update-install'){if(window.Android)Android.installUpdate();}
  else if(action==='update-browser'){if(window.Android)Android.openRelease();else window.open('https://github.com/qi-fg/wordleaf/releases/latest','_blank','noopener');}
  else if(action==='about'){modal={type:'about'};renderModal();}
  else if(action==='export')exportBackup();
  else if(action==='import'){if(window.Android)Android.importBackup();else document.getElementById('backup-file').click();}
  else if(action==='restore'){stopTick();library=modal.data;useBook(library.activeMode,library.books[library.activeMode]);state=library.books[activeMode];readFailed=false;modal=null;study=null;undoAction=null;query='';filter='all';tierFilter='all';limit=50;page='stats';save();render();toast('备份已恢复。');}
});
document.addEventListener('submit',event=>{if(event.target.id==='plan-form'){event.preventDefault();applyPlan();}else if(event.target.id==='spell-form'){event.preventDefault();checkSpelling();}});
document.addEventListener('input',event=>{
  if(event.target.id==='search'){query=event.target.value;limit=50;const list=filteredWords();document.getElementById('result-count').textContent=`${list.length} 个词条`;document.getElementById('word-list').innerHTML=wordList(list);}
  if(event.target.id==='spell-input'&&study){study.spell.answer=event.target.value;persistSession();}
  if(event.target.closest('#plan-form'))updatePlanPreview();
});
document.addEventListener('change',event=>{
  if(event.target.id==='review-goal'){state.reviewGoal=Number(event.target.value);save();toast('复习额度已更新，下一轮按新额度安排。');}
  if(event.target.id==='goal'){state.goal=Number(event.target.value);save();toast(today().newTarget?'新目标已保存，从明天开始使用；今日目标保持不变。':'每日目标已更新。');}
  if(event.target.id==='tier-filter'){tierFilter=event.target.value;limit=50;renderBook();}
  if(event.target.closest('#plan-form'))updatePlanPreview();
  if(event.target.id==='wordlist-file'){const f=event.target.files[0];if(f){if(f.size>3000000)toast('词表文件过大。');else{const reader=new FileReader();reader.onload=()=>window.receiveWordlist(reader.result);reader.onerror=()=>toast('无法读取词表。');reader.readAsText(f);}}event.target.value='';}
  if(event.target.id==='backup-file'){const f=event.target.files[0];if(f){if(f.size>5000000)toast('备份文件过大。');else{const reader=new FileReader();reader.onload=()=>window.receiveBackup(reader.result);reader.onerror=()=>toast('无法读取文件。');reader.readAsText(f);}}event.target.value='';}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape')window.appBack();if(event.key==='Tab'&&modal){const items=[...document.querySelectorAll('.modal button,.modal summary,.modal select,.modal input')].filter(el=>!el.disabled&&el.getClientRects().length);if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTick();persistSession();}else if((page==='home'||page==='stats')&&!modal)render();else if(page==='study'||page==='spell')startTick();});
window.addEventListener('pagehide',()=>{stopTick();persistSession();});
window.pauseLearningClock=at=>{accountTime(at);persistSession();};
window.resumeLearningClock=at=>{if(study&&(page==='study'||page==='spell')&&!study.pause&&unfinished(study))tick=at;};
// Allow vertical scrolling and input selection while suppressing multi-touch page zoom.
document.addEventListener('touchstart',event=>{if(event.touches.length>1)event.preventDefault();},{passive:false});
document.addEventListener('touchmove',event=>{if(event.touches.length>1)event.preventDefault();},{passive:false});
document.addEventListener('gesturestart',event=>event.preventDefault(),{passive:false});
let displayedDay=dayKey();
setInterval(()=>{if(!document.hidden&&!modal&&(page==='home'||page==='stats')&&displayedDay!==dayKey()){displayedDay=dayKey();render();}},30000);
render();
